import base64, zlib, os
FILES = {
  "main.py": "",
  "dashboard/public/app.js": "",
  "scanner/open_redirect.py": "",
  "scanner/cors_scanner.py": "",
  "scanner/http_methods.py": "",
  "scanner/info_leak.py": "",
  "scanner/cookie_audit.py": "",
  "scanner/clickjacking.py": ""
}


ROOT = os.path.dirname(os.path.abspath(__file__))
for target, encoded in FILES.items():
    content = zlib.decompress(base64.b64decode(encoded))
    filepath = os.path.join(ROOT, target)
    os.makedirs(os.path.dirname(filepath), exist_ok=True)
    with open(filepath, "wb") as f:
        f.write(content)
    print(f"  Written: {target} ({len(content)} bytes)")
print()
print("SpencerWeb v3 — 16 modules patched!")
print("Now run:")
print("  rmdir /s /q scanner\__pycache__")
print("  cd dashboard && node server.js")
